#include "RoomQualityRuntime.hpp"
namespace elysium::fortress {bool RoomQualityRuntime::upsert(RoomPolicy p){if(!p.id||!p.type)return false;rooms_[p.id]=std::move(p);return true;}RoomQuality RoomQualityRuntime::evaluate(StableId id,const RoomQualityInputs&i)const{RoomQuality q{};if(!rooms_.count(id))return q;auto add=[&](const char*n,double v){v=std::clamp(std::isfinite(v)?v:0.0,-1.0,1.0);q.contributions.push_back({n,v});q.total+=v;};add("area",i.area);add("material",i.materialValue);add("craftsmanship",i.craftsmanship);add("cleanliness",i.cleanliness);add("decor",i.decor);add("privacy",i.privacy);add("noise",-std::abs(i.noise));add("comfort",i.comfort);add("safety",i.safety);add("view",i.view);add("culture",i.culture);add("personality",i.personality);return q;}}
